def _variants(t):
    import html as _h
    base = _h.escape(t, quote=False)
    out = {t, base}
    for v in list(out):
        out.add(v.replace('—', '&mdash;'))
    return out


def apply_text():
    import glob as _g
    missing = 0
    for rel, pairs in TEXT_FIXES.items():
        files = [rel] if rel != '*' else [f for f in _g.glob(str(root / '**/*.html'), recursive=True)
                                          if '/id/' not in f and '/partials/' not in f]
        for f in files:
            p = pathlib.Path(f) if rel == '*' else root / rel
            s = p.read_text(encoding='utf-8'); orig = s
            for old, new in pairs:
                hit = False
                for v in _variants(old):
                    if '>' + v + '<' in s or ('>' + v) in s:
                        s = s.replace('>' + v + '<', '>' + __import__('html').escape(new, quote=False) + '<')
                        s = s.replace('>' + v, '>' + __import__('html').escape(new, quote=False))
                        hit = True
                if not hit and rel != '*' and __import__('html').escape(new, quote=False) not in s:
                    missing += 1; print(f'TIDAK KETEMU [{rel}]: {old[:80]}')
            if s != orig:
                p.write_text(s, encoding='utf-8')
    print('teks polos selesai; tidak ketemu:', missing)


apply_text()
